-- =============================================================================
-- REX COLORSCHEME ENGINE
-- PURPOSE: Build a complete Neovim colourscheme from a Rex terminal palette
-- (background, foreground, cursor, selection and sixteen ANSI colours).
-- The per-theme files in `colors/rex-*.lua` are generated by
-- `config/theme/rex-to-nvim.py` and only carry data; all mapping lives here.
-- =============================================================================

local RexColorscheme = {}


---@class RexPalette
---@field name string Colourscheme name, e.g. "rex-merino-dark"
---@field appearance "dark"|"light"
---@field background string
---@field foreground string
---@field cursor string
---@field selection_background string
---@field selection_foreground string
---@field ansi string[] Sixteen colours, index 1 = ANSI 0

---Split "#rrggbb" into 0-255 components.
---@param hex string
---@return number r, number g, number b
local function to_rgb(hex)
	local h = hex:gsub("^#", "")
	return tonumber(h:sub(1, 2), 16), tonumber(h:sub(3, 4), 16), tonumber(h:sub(5, 6), 16)
end

---Linear mix of two colours in sRGB: `t = 0` gives `a`, `t = 1` gives `b`.
---@param a string
---@param b string
---@param t number
---@return string
local function mix(a, b, t)
	local ar, ag, ab = to_rgb(a)
	local br, bg, bb = to_rgb(b)
	return string.format(
		"#%02x%02x%02x",
		math.floor(ar + (br - ar) * t + 0.5),
		math.floor(ag + (bg - ag) * t + 0.5),
		math.floor(ab + (bb - ab) * t + 0.5)
	)
end

---Derive the working colour set from the terminal palette.
---@param p RexPalette
---@return table<string, string>
local function derive(p)
	local bg, fg = p.background, p.foreground
	local a = p.ansi
	return {
		bg = bg,
		fg = fg,
		-- Surfaces step towards the foreground, which works for light and dark alike.
		bg_soft = mix(bg, fg, 0.05),
		bg_float = mix(bg, fg, 0.08),
		bg_line = mix(bg, fg, 0.10),
		border = mix(bg, fg, 0.28),
		-- Mixes chosen so comments reach about 3:1 contrast or better on all 41
		-- Rex themes (mean about 4.6:1); 0.45 left several light themes below 2.5:1.
		muted = mix(bg, fg, 0.60),
		subtle = mix(bg, fg, 0.75),
		sel_bg = p.selection_background,
		sel_fg = p.selection_foreground,
		cursor = p.cursor,
		red = a[2],
		green = a[3],
		yellow = a[4],
		blue = a[5],
		magenta = a[6],
		cyan = a[7],
		bright_red = a[10],
		bright_green = a[11],
		bright_yellow = a[12],
		bright_blue = a[13],
		bright_magenta = a[14],
		bright_cyan = a[15],
		-- Tinted backgrounds for diffs and diagnostics.
		diff_add = mix(bg, a[3], 0.20),
		diff_change = mix(bg, a[5], 0.20),
		diff_delete = mix(bg, a[2], 0.20),
		diff_text = mix(bg, a[5], 0.38),
	}
end

---Apply every highlight group for a derived colour set.
---@param c table<string, string>
local function apply_highlights(c)
	---@param group string
	---@param spec table
	local function hl(group, spec)
		vim.api.nvim_set_hl(0, group, spec)
	end

	-- Editor chrome ----------------------------------------------------------
	hl("Normal", { fg = c.fg, bg = c.bg })
	hl("NormalNC", { fg = c.fg, bg = c.bg })
	hl("NormalFloat", { fg = c.fg, bg = c.bg_float })
	hl("FloatBorder", { fg = c.border, bg = c.bg_float })
	hl("FloatTitle", { fg = c.blue, bg = c.bg_float, bold = true })
	hl("Cursor", { fg = c.bg, bg = c.cursor })
	hl("lCursor", { link = "Cursor" })
	hl("CursorIM", { link = "Cursor" })
	hl("TermCursor", { link = "Cursor" })
	hl("CursorLine", { bg = c.bg_line })
	hl("CursorColumn", { bg = c.bg_line })
	hl("ColorColumn", { bg = c.bg_soft })
	hl("LineNr", { fg = c.muted })
	hl("CursorLineNr", { fg = c.fg, bold = true })
	hl("SignColumn", { fg = c.muted, bg = c.bg })
	hl("FoldColumn", { fg = c.muted, bg = c.bg })
	hl("Folded", { fg = c.subtle, bg = c.bg_soft })
	hl("VertSplit", { fg = c.border })
	hl("WinSeparator", { fg = c.border })
	hl("EndOfBuffer", { fg = c.bg })
	hl("NonText", { fg = c.border })
	hl("Whitespace", { fg = c.border })
	hl("SpecialKey", { fg = c.border })
	hl("Conceal", { fg = c.muted })
	hl("Directory", { fg = c.blue })
	hl("Title", { fg = c.blue, bold = true })
	hl("MatchParen", { fg = c.bright_yellow, bold = true, underline = true })
	hl("Visual", { fg = c.sel_fg, bg = c.sel_bg })
	hl("VisualNOS", { link = "Visual" })
	hl("Search", { fg = c.bg, bg = c.yellow })
	hl("CurSearch", { fg = c.bg, bg = c.bright_yellow, bold = true })
	hl("IncSearch", { link = "CurSearch" })
	hl("Substitute", { fg = c.bg, bg = c.red })
	hl("QuickFixLine", { bg = c.bg_line, bold = true })
	hl("WildMenu", { fg = c.sel_fg, bg = c.sel_bg })

	-- Status, tabs, popups ---------------------------------------------------
	hl("StatusLine", { fg = c.fg, bg = c.bg_line })
	hl("StatusLineNC", { fg = c.muted, bg = c.bg_soft })
	hl("TabLine", { fg = c.muted, bg = c.bg_soft })
	hl("TabLineFill", { bg = c.bg_soft })
	hl("TabLineSel", { fg = c.fg, bg = c.bg, bold = true })
	hl("WinBar", { fg = c.fg, bg = c.bg })
	hl("WinBarNC", { fg = c.muted, bg = c.bg })
	hl("Pmenu", { fg = c.fg, bg = c.bg_float })
	hl("PmenuSel", { fg = c.sel_fg, bg = c.sel_bg })
	hl("PmenuSbar", { bg = c.bg_line })
	hl("PmenuThumb", { bg = c.muted })
	hl("MsgArea", { fg = c.fg })
	hl("ModeMsg", { fg = c.green, bold = true })
	hl("MoreMsg", { fg = c.green })
	hl("Question", { fg = c.blue })
	hl("ErrorMsg", { fg = c.red, bold = true })
	hl("WarningMsg", { fg = c.yellow })

	-- Syntax -----------------------------------------------------------------
	hl("Comment", { fg = c.muted, italic = true })
	hl("Constant", { fg = c.yellow })
	hl("String", { fg = c.green })
	hl("Character", { fg = c.green })
	hl("Number", { fg = c.yellow })
	hl("Boolean", { fg = c.yellow })
	hl("Float", { fg = c.yellow })
	hl("Identifier", { fg = c.fg })
	hl("Function", { fg = c.blue })
	hl("Statement", { fg = c.magenta })
	hl("Conditional", { fg = c.magenta })
	hl("Repeat", { fg = c.magenta })
	hl("Label", { fg = c.magenta })
	hl("Operator", { fg = c.subtle })
	hl("Keyword", { fg = c.magenta })
	hl("Exception", { fg = c.magenta })
	hl("PreProc", { fg = c.bright_magenta })
	hl("Include", { fg = c.bright_magenta })
	hl("Define", { fg = c.bright_magenta })
	hl("Macro", { fg = c.bright_magenta })
	hl("PreCondit", { fg = c.bright_magenta })
	hl("Type", { fg = c.cyan })
	hl("StorageClass", { fg = c.cyan })
	hl("Structure", { fg = c.cyan })
	hl("Typedef", { fg = c.cyan })
	hl("Special", { fg = c.bright_cyan })
	hl("SpecialChar", { fg = c.bright_cyan })
	hl("Tag", { fg = c.blue })
	hl("Delimiter", { fg = c.subtle })
	hl("SpecialComment", { fg = c.subtle, italic = true })
	hl("Debug", { fg = c.red })
	hl("Underlined", { fg = c.blue, underline = true })
	hl("Ignore", { fg = c.muted })
	hl("Error", { fg = c.red })
	hl("Todo", { fg = c.bg, bg = c.yellow, bold = true })

	-- Treesitter and LSP semantics ------------------------------------------
	hl("@variable", { fg = c.fg })
	hl("@variable.builtin", { fg = c.bright_red })
	hl("@variable.parameter", { fg = c.bright_yellow })
	hl("@variable.member", { fg = c.fg })
	hl("@property", { fg = c.fg })
	hl("@constant", { link = "Constant" })
	hl("@constant.builtin", { fg = c.bright_yellow })
	hl("@module", { fg = c.cyan })
	hl("@string.escape", { fg = c.bright_cyan })
	hl("@string.regexp", { fg = c.bright_cyan })
	hl("@function.builtin", { fg = c.bright_blue })
	hl("@function.macro", { fg = c.bright_magenta })
	hl("@constructor", { fg = c.cyan })
	hl("@keyword.function", { fg = c.magenta })
	hl("@keyword.return", { fg = c.magenta })
	hl("@punctuation.delimiter", { fg = c.subtle })
	hl("@punctuation.bracket", { fg = c.subtle })
	hl("@comment.todo", { link = "Todo" })
	hl("@comment.error", { fg = c.red, bold = true })
	hl("@comment.warning", { fg = c.yellow, bold = true })
	hl("@comment.note", { fg = c.blue, bold = true })
	hl("@markup.heading", { fg = c.blue, bold = true })
	hl("@markup.strong", { bold = true })
	hl("@markup.italic", { italic = true })
	hl("@markup.strikethrough", { strikethrough = true })
	hl("@markup.link", { fg = c.blue })
	hl("@markup.link.url", { fg = c.blue, underline = true })
	hl("@markup.raw", { fg = c.green })
	hl("@markup.list", { fg = c.magenta })
	hl("@tag", { fg = c.blue })
	hl("@tag.attribute", { fg = c.cyan })
	hl("@tag.delimiter", { fg = c.subtle })
	hl("@lsp.type.parameter", { link = "@variable.parameter" })
	hl("@lsp.type.property", { link = "@property" })

	-- Diagnostics ------------------------------------------------------------
	local diagnostics = {
		Error = c.red,
		Warn = c.yellow,
		Info = c.blue,
		Hint = c.cyan,
		Ok = c.green,
	}
	for kind, colour in pairs(diagnostics) do
		hl("Diagnostic" .. kind, { fg = colour })
		hl("DiagnosticVirtualText" .. kind, { fg = colour, bg = mix(c.bg, colour, 0.10) })
		hl("DiagnosticUnderline" .. kind, { sp = colour, undercurl = true })
		hl("DiagnosticSign" .. kind, { fg = colour })
	end
	hl("SpellBad", { sp = c.red, undercurl = true })
	hl("SpellCap", { sp = c.yellow, undercurl = true })
	hl("SpellLocal", { sp = c.cyan, undercurl = true })
	hl("SpellRare", { sp = c.magenta, undercurl = true })

	-- Diffs and VCS ----------------------------------------------------------
	hl("DiffAdd", { bg = c.diff_add })
	hl("DiffChange", { bg = c.diff_change })
	hl("DiffDelete", { fg = c.red, bg = c.diff_delete })
	hl("DiffText", { bg = c.diff_text })
	hl("Added", { fg = c.green })
	hl("Changed", { fg = c.blue })
	hl("Removed", { fg = c.red })
	hl("GitSignsAdd", { fg = c.green })
	hl("GitSignsChange", { fg = c.blue })
	hl("GitSignsDelete", { fg = c.red })
end

---Set the sixteen terminal colours used by `:terminal`.
---@param ansi string[]
local function apply_terminal_colours(ansi)
	for index, colour in ipairs(ansi) do
		vim.g["terminal_color_" .. (index - 1)] = colour
	end
end

---Load a colourscheme from a Rex palette.
---@param palette RexPalette
function RexColorscheme.load(palette)
	if type(palette) ~= "table" or type(palette.ansi) ~= "table" or #palette.ansi < 16 then
		vim.notify("rex-colorscheme: incomplete palette", vim.log.levels.ERROR)
		return
	end

	vim.cmd("highlight clear")
	if vim.fn.exists("syntax_on") == 1 then
		vim.cmd("syntax reset")
	end
	vim.o.termguicolors = true
	vim.o.background = palette.appearance
	vim.g.colors_name = palette.name

	apply_highlights(derive(palette))
	apply_terminal_colours(palette.ansi)
end

-- Exposed for tests.
RexColorscheme._mix = mix

return RexColorscheme
